import math
import torch

def gen_inputs(ctx, device):
    hidden_size = int(ctx["w_hh__shape"][0])
    bound = 1.0 / math.sqrt(hidden_size)
    result = {}
    for name in ("w_ih", "w_hh", "b_ih", "b_hh"):
        dtype = getattr(torch, ctx[f"{name}__dtype"])
        result[name] = torch.empty(
            ctx[f"{name}__shape"], dtype=dtype, device=device
        ).uniform_(-bound, bound)
    return result

def run(input, hx, w_ih, w_hh, b_ih, b_hh, has_biases, num_layers, dropout, train, bidirectional, batch_first):
    params = [w_ih, w_hh, b_ih, b_hh]
    return torch.rnn_relu(input, hx, params, has_biases, num_layers, dropout, train, bidirectional, batch_first)
